import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Utils/Extensions/responsive.dart';import '../../../../Config/app_config.dart';import 'authentication_split1.dart';import 'authentication_split2.dart';class AuthenticationBody extends StatelessWidget {  const AuthenticationBody({    super.key,  });  @override  Widget build(BuildContext context) {    List<Widget> list = [      AuthenticationSplit1(),      AuthenticationSplit2(),    ];    return Scaffold(      body: SafeArea(        child: CustomScrollView(          physics: AppConfig.physicsCustomScrollView,          slivers: [            SliverFillRemaining(              hasScrollBody: false,              fillOverscroll: true,              child: context.isSmallScreen                  ? Column(                      spacing: 50.h,                      children: list,                    )                  : Row(                      children: list,                    ),            )          ],        ),      ),    );  }}